refused_program.body:
set -e
tmp=$(mktemp)
awk '
  function trim(s) { sub(/^[[:space:]]+/, "", s); sub(/[[:space:]]+$/, "", s); return s }
  NR==FNR {
    line=$0
    sub(/#.*/, "", line)
    if (line ~ /^[[:space:]]*$/) next
    eq=index(line,"=")
    if (eq == 0) next
    old=trim(substr(line,1,eq-1))
    new=trim(substr(line,eq+1))
    if (old != "" && new != "") map[old]=new
    next
  }
  {
    line=$0
    if (line ~ /^[[:space:]]*#/) { print; next }
    if (match(line, /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/)) {
      indent=line
      sub(/[^[:space:]].*$/, "", indent)
      rest=substr(line, length(indent)+1)
      if (match(rest, /^[A-Za-z0-9_.-]+/)) {
        key=substr(rest, RSTART, RLENGTH)
        if (key in map) {
          tail=substr(rest, RLENGTH+1)
          print indent map[key] tail
          next
        }
      }
    }
    print
  }
' config/renames.conf config/settings.conf > "$tmp" || { rm -f "$tmp"; exit 1; }
mv "$tmp" config/settings.conf || { rm -f "$tmp"; exit 1; }
git add config/settings.conf
git -c user.name="settings-migration" -c user.email="settings-migration@example.invalid" commit -m "chore: migrate settings keys to current names" -- config/settings.conf

postconditions.probe:
awk '
  function trim(s) { sub(/^[[:space:]]+/, "", s); sub(/[[:space:]]+$/, "", s); return s }
  function parse_line(line,    indent, rest, key, tail) {
    if (line ~ /^[[:space:]]*#/) return ""
    if (!match(line, /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/)) return ""
    indent=line
    sub(/[^[:space:]].*$/, "", indent)
    rest=substr(line, length(indent)+1)
    if (!match(rest, /^[A-Za-z0-9_.-]+/)) return ""
    key=substr(rest, RSTART, RLENGTH)
    tail=substr(rest, RLENGTH+1)
    sub(/^[[:space:]]*=[[:space:]]*/, "", tail)
    return key SUBSEP trim(tail)
  }
  NR==FNR {
    line=$0
    sub(/#.*/, "", line)
    if (line ~ /^[[:space:]]*$/) next
    eq=index(line,"=")
    if (eq == 0) next
    old=trim(substr(line,1,eq-1))
    new=trim(substr(line,eq+1))
    if (old != "" && new != "") map[old]=new
    next
  }
  FNR==1 { stage++ }
  stage==1 {
    kv=parse_line($0)
    if (kv != "") {
      split(kv, a, SUBSEP)
      oldval[a[1]]=a[2]
    }
    next
  }
  stage==2 {
    kv=parse_line($0)
    if (kv != "") {
      split(kv, a, SUBSEP)
      newval[a[1]]=a[2]
    }
    next
  }
  END {
    ok=1
    for (old in map) {
      if (old in oldval) {
        new=map[old]
        if (old in newval) ok=0
        if (!(new in newval)) ok=0
        else if (newval[new] != oldval[old]) ok=0
      }
    }
    exit ok ? 0 : 1
  }
' config/renames.conf <(git show HEAD^:config/settings.conf) <(git show HEAD:config/settings.conf)

preconditions.probe:
awk '
  function trim(s) { sub(/^[[:space:]]+/, "", s); sub(/[[:space:]]+$/, "", s); return s }
  NR==FNR {
    line=$0
    sub(/#.*/, "", line)
    if (line ~ /^[[:space:]]*$/) next
    eq=index(line,"=")
    if (eq == 0) next
    old=trim(substr(line,1,eq-1))
    new=trim(substr(line,eq+1))
    if (old != "" && new != "") map[old]=new
    next
  }
  {
    line=$0
    if (line ~ /^[[:space:]]*#/) next
    if (match(line, /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/)) {
      indent=line
      sub(/[^[:space:]].*$/, "", indent)
      rest=substr(line, length(indent)+1)
      if (match(rest, /^[A-Za-z0-9_.-]+/)) {
        key=substr(rest, RSTART, RLENGTH)
        present[key]=1
      }
    }
  }
  END {
    stale=0
    conflict=0
    for (old in map) {
      if (map[old] in map) conflict=1
      if (old in present) {
        if (map[old] in present) conflict=1
        else stale=1
      }
    }
    for (a in map) {
      for (b in map) {
        if (a != b && map[a] == map[b] && (a in present) && (b in present)) conflict=1
      }
    }
    exit (stale && !conflict) ? 0 : 1
  }
' config/renames.conf config/settings.conf
